<?php
use App\Models\{Guru,Kelas,MataPelajaran,NilaiTugas,Pengajaran,PengaturanSekolah,Semester,Siswa}; use App\Services\GenerateLaporan; use Livewire\Attributes\Url; use Livewire\Component;
new class extends Component { public string $jenis='jadwal'; #[Url] public string $semesterId='';#[Url]public string $kelasId='';#[Url]public string $guruId='';#[Url]public string $mapelId='';#[Url]public string $siswaId='';#[Url]public string $hari='';#[Url]public int $bulan=8;
public function mount(?string $jenis=null):void{$this->jenis=$jenis??request()->route('jenis','jadwal');$this->bulan=(int)(request('bulan')?:now()->month);}
public function with():array{$u=auth()->user();if($u->hasRole('siswa')){$this->siswaId=(string)$u->siswa?->id;$this->kelasId=(string)($u->siswa?->penempatanKelas()->where('status','aktif')->value('kelas_id')??'');}if($u->hasRole('guru'))$this->guruId=(string)$u->guru?->id;$filter=['semester_id'=>$this->semesterId,'kelas_id'=>$this->kelasId,'guru_id'=>$this->guruId,'hari'=>$this->hari,'bulan'=>$this->bulan,'siswa_id'=>$this->siswaId];$rows=$this->jenis==='jadwal'?app(GenerateLaporan::class)->jadwal($filter):NilaiTugas::with(['siswa','pengajaran.semester.tahunAjaran','pengajaran.kelas','pengajaran.guru','pengajaran.mataPelajaran'])->where('bulan',$this->bulan)->when($this->semesterId,fn($q)=>$q->whereHas('pengajaran',fn($x)=>$x->where('semester_id',$this->semesterId)))->when($this->kelasId,fn($q)=>$q->whereHas('pengajaran',fn($x)=>$x->where('kelas_id',$this->kelasId)))->when($this->guruId,fn($q)=>$q->whereHas('pengajaran',fn($x)=>$x->where('guru_id',$this->guruId)))->when($this->mapelId,fn($q)=>$q->whereHas('pengajaran',fn($x)=>$x->where('mata_pelajaran_id',$this->mapelId)))->when($this->siswaId,fn($q)=>$q->where('siswa_id',$this->siswaId))->get()->groupBy(fn($n)=>$n->pengajaran_id.'-'.$n->siswa_id);return ['rows'=>$rows,'sekolah'=>PengaturanSekolah::first(),'semesters'=>Semester::with('tahunAjaran')->get(),'kelas'=>Kelas::orderBy('nama')->get(),'guru'=>Guru::orderBy('nama_lengkap')->get(),'mapel'=>MataPelajaran::orderBy('nama')->get(),'siswa'=>Siswa::orderBy('nama_lengkap')->get()];}
public function average($rows):string{$v=$rows->whereNotNull('nilai')->pluck('nilai');return $v->isEmpty()?'-':number_format($v->avg(),2);}}; ?>
<div><div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold text-sky-700">Laporan</p><h1 class="page-title">Laporan {{ucfirst($jenis)}}</h1><p class="page-subtitle">Preview web siap cetak dan unduh PDF.</p></div><div class="print-hidden flex gap-2"><button onclick="window.print()" class="btn-secondary">Cetak</button><a href="{{route('laporan.pdf',['jenis'=>$jenis,'semester_id'=>$semesterId,'kelas_id'=>$kelasId,'guru_id'=>$guruId,'mapel_id'=>$mapelId,'siswa_id'=>$siswaId,'hari'=>$hari,'bulan'=>$bulan])}}" class="btn-primary">Unduh PDF</a></div></div>
<form class="filters card mb-5 grid gap-3 p-4 sm:grid-cols-2 xl:grid-cols-4"><select wire:model.live="semesterId" class="form-input"><option value="">Semua semester</option>@foreach($semesters as $s)<option value="{{$s->id}}">{{$s->tahunAjaran->nama}} · {{ucfirst($s->nama)}}</option>@endforeach</select><select wire:model.live="kelasId" class="form-input"><option value="">Semua kelas</option>@foreach($kelas as $k)<option value="{{$k->id}}">{{$k->nama}}</option>@endforeach</select>@unless(auth()->user()->hasRole(['guru','siswa']))<select wire:model.live="guruId" class="form-input"><option value="">Semua guru</option>@foreach($guru as $g)<option value="{{$g->id}}">{{$g->nama_lengkap}}</option>@endforeach</select>@endunless@if($jenis==='jadwal')<select wire:model.live="hari" class="form-input"><option value="">Semua hari</option>@foreach(['senin','selasa','rabu','kamis','jumat','sabtu'] as $h)<option value="{{$h}}">{{ucfirst($h)}}</option>@endforeach</select>@else<select wire:model.live="mapelId" class="form-input"><option value="">Semua mata pelajaran</option>@foreach($mapel as $m)<option value="{{$m->id}}">{{$m->nama}}</option>@endforeach</select><select wire:model.live="bulan" class="form-input">@foreach(range(1,12) as $m)<option value="{{$m}}">{{\Carbon\Carbon::create()->month($m)->translatedFormat('F')}}</option>@endforeach</select>@unless(auth()->user()->hasRole('siswa'))<select wire:model.live="siswaId" class="form-input"><option value="">Semua siswa</option>@foreach($siswa as $s)<option value="{{$s->id}}">{{$s->nama_lengkap}}</option>@endforeach</select>@endunless@endif</form>
<section class="card overflow-hidden"><div class="border-b p-6 text-center"><h2 class="font-semibold uppercase text-slate-950">{{$sekolah?->nama_sekolah??'SD Negeri 232 Maluku Tengah'}}</h2>@if($sekolah?->alamat)<p class="mt-1 text-sm text-slate-500">{{$sekolah->alamat}}</p>@endif<p class="mt-2 text-lg font-bold uppercase">Laporan {{ucfirst($jenis)}} {{ $jenis==='nilai'?'Tugas Siswa':'' }}</p><p class="mt-2 text-sm text-slate-500">Dicetak {{now()->translatedFormat('d F Y H:i')}} WIT</p></div><div class="table-scroll"><table class="data-table"><thead>@if($jenis==='jadwal')<tr><th>Hari</th><th>Jam</th><th>Kelas</th><th>Mata Pelajaran</th><th>Guru</th></tr>@else<tr><th>No</th><th>NIS/NISN</th><th>Nama Siswa</th><th>Mata Pelajaran</th><th>M1</th><th>M2</th><th>M3</th><th>M4</th><th>Rata-rata</th></tr>@endif</thead><tbody>@if($jenis==='jadwal')@forelse($rows as $r)<tr><td class="capitalize">{{$r->hari}}</td><td>{{substr($r->jamPelajaran->jam_mulai,0,5)}}–{{substr($r->jamPelajaran->jam_selesai,0,5)}}</td><td>{{$r->pengajaran->kelas->nama}}</td><td>{{$r->pengajaran->mataPelajaran->nama}}</td><td>{{$r->pengajaran->guru->nama_lengkap}}</td></tr>@empty<tr><td colspan="5" class="py-12 text-center">Belum ada jadwal pada filter ini.</td></tr>@endforelse @else @forelse($rows as $group)@php $f=$group->first(); @endphp<tr><td>{{$loop->iteration}}</td><td>{{$f->siswa->nis??$f->siswa->nisn??'-'}}</td><td>{{$f->siswa->nama_lengkap}}</td><td>{{$f->pengajaran->mataPelajaran->nama}}</td>@foreach(range(1,4) as $w)<td>{{$group->firstWhere('minggu',$w)?->nilai??'-'}}</td>@endforeach<td>{{$this->average($group)}}</td></tr>@empty<tr><td colspan="9" class="py-12 text-center">Belum ada nilai pada filter ini.</td></tr>@endforelse @endif</tbody></table></div></section></div>
